            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Un peu de repos ! Du repos, et des seuils chauds pour boire le soleil et fumer la pipe.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "De la peau qui tourne au vent de nuit et bourdonne comme un tambour, des larmes de sang noir pleurent dans l'herbe.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Les choses de la terre, mon vieux, j'ai tant vécu avec elles, j'ai tant fait ma vie dans l'espace qu'elles laissaient, j'ai tant eu d'amis arbres, le vent s'est tant frotté contre moi que, quand j'ai de la peine, c'est à elles que je pense pour la consolation.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Dans toi il n'y a déjà plus d'homme, il n'y a plus que la matière de cent sauterelles neuves, de dix lézards, de trois serpents, d'un beau rectangle d'herbe drue et peut-être le cœur d'un arbre.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "On écorcha l'anguille encore vive et la peau se gonflait au vent. On mit le bardeau sur un gril de fer et, dans un feu de sarment, tout ça se mit à cuire; court-bouillon de fenouil et grillades. La jeune fille arrosait le poisson d'un huile minutieuse.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "« Le monde se trompe, dit Bobi. Vous croyez que c'est ce que vous gardez qui vous fait riche. On vous l'a dit. Moi je vous dis que c'est ce que vous donnez qui vous fait riche.»", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "« Vous n'avez d'autre grange que cette grange-là, dit-il en frappant la poitrine. Tout ce que vous entassez hors de votre cœur est perdu.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Pour ceux qui sont nés en captivité, la liberté n'est plus un aliment.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Je suis le compagnon en perpétuelle révolte contre ta captivité, qui que tu sois, et si tu n'es pas révolté en toi-même, soit que le travail ait tué toutes tes facultés de révolte, soit que tu aies pris goût à tes vices, je suis révolté pour toi malgré tout pour t'obliger à l'être.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Car la richesse de l'homme est dans son cœur. C'est dans son cœur qu'il est le roi du monde. Vivre n'exige pas la possession de tant de choses.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Nous sommes dans l'extrême multiplication des générations que la technique industrielle a entassées dans les villes.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Car, qui envisage le gain doit envisager la perte. Ça n'est pas marqué dans le prospectus mais si vous réclamez après on vous dira : « Voyons, ça allait de soi. On avait pensé qu’il était inutile de vous le dire ; c’est si naturel ! »", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Il ne suffit pas d’être pacifiste, même si c’est du fond du cœur et dans une farouche sincérité ; il faut que ce pacifisme soit la philosophie directrice de tous les actes de votre vie.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Dans les temps modernes, l’humble sagesse est la pensée la plus révolutionnaire du monde.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "J’avais l’habitude de ces détrousseurs de grands chemins : ils ne sont pas courageux ; s’ils étaient courageux, ils travailleraient.", Author = "Jean Giono" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Giono", Text = "Je crois à la vertu de l’homme à cheval, mais il faut qu’il reste muet. S’il prononce un mot, c’est comme s’il mettait pied à terre.", Author = "Jean Giono" },
